// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (ripple-*) and colors (--ripple-*). Loops forever. React 19
// hoists this <style> into <head> once, however many instances render.
const css = `
[data-slot="ripple-waves"] {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 220px;
  aspect-ratio: 1;
}
[data-slot="ripple-waves"]::before,
[data-slot="ripple-waves"]::after {
  content: "";
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background-color: var(--ripple-wave, #ccc);
  animation: ripple-fade-in-out 1.6s ease-out both infinite;
}
[data-slot="ripple-waves"]::before {
  animation-delay: 0s;
}
[data-slot="ripple-waves"]::after {
  animation-delay: 0.4s;
}
@keyframes ripple-fade-in-out {
  from {
    opacity: 1;
    transform: scale(0);
  }
  80%,
  to {
    opacity: 0;
    transform: scale(1);
  }
}

/* Paused: the waves hold their current frame (WCAG 2.2.2 Pause, Stop, Hide). */
[data-slot="ripple"][data-paused] [data-slot="ripple-waves"]::before,
[data-slot="ripple"][data-paused] [data-slot="ripple-waves"]::after {
  animation-play-state: paused;
}

/* Optional content, centered above the waves. */
[data-slot="ripple-content"] {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

/*
 * Reduced motion: opacity only. The waves keep their full size and only
 * pulse.
 */
@keyframes ripple-fade {
  from {
    opacity: 1;
  }
  80%,
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="ripple-waves"]::before,
  [data-slot="ripple-waves"]::after {
    animation-name: ripple-fade;
  }
}
`;

export interface RippleProps extends React.ComponentProps<"div"> {
  /** Holds the waves on their current frame. It loops forever otherwise. */
  paused?: boolean;
}

/**
 * Waves spread out from the center and fade, in a loop. Children render
 * centered above the waves (an avatar, a status dot). Offer a way to pause
 * it (`paused`) wherever it plays next to other content.
 */
function Ripple({
  className,
  children,
  paused = false,
  ...props
}: RippleProps) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  const decorative = !labelled && children == null;
  return (
    <div
      data-slot="ripple"
      data-paused={paused ? "" : undefined}
      role={labelled && children == null ? "img" : undefined}
      aria-hidden={decorative ? true : undefined}
      className={cn(
        "relative aspect-square w-full max-w-80 overflow-hidden bg-[var(--ripple-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-ripple" precedence="default">
        {css}
      </style>
      <div data-slot="ripple-waves" aria-hidden="true" />
      {children == null ? null : (
        <div data-slot="ripple-content">{children}</div>
      )}
    </div>
  );
}

export { Ripple };
